 "gfx12-sh-pairs": {
  "id": "gfx12-sh-pairs",
  "title": "GFX12: SET_SH_REG_PAIRS",
  "layer": "pal",
  "repo": "pal",
  "path": "src/core/hw/gfxip/gfx12/gfx12CmdUtil.cpp",
  "explain": "Register-<em>pair</em> packets ((offset, value) pairs in one packet, so scattered registers don't each need their own contiguous-range SET_SH_REG) first appear for GFX11, where the Gfx9 HWL emits packed variants such as <code>IT_SET_SH_REG_PAIRS_PACKED__GFX11</code>. The GFX12 HWL builds <code>IT_SET_SH_REG_PAIRS</code> headers directly, as here.",
  "symbols": [
   "IT_SET_SH_REG_PAIRS"
  ],
  "refs": [],
  "start": 340,
  "end": 356,
  "code": "size_t CmdUtil::BuildSetShPairsHeader(\n    uint32 numPairsTotal,\n    void** ppDataStart, // [out] Pointer to where the register pair data starts.\n    void*  pBuffer)\n{\n    // The packet itself contains at least one pair.\n    PAL_ASSERT(numPairsTotal > 0);\n    const uint32 packetSize = PM4_PFP_SET_SH_REG_PAIRS_SIZEDW__CORE + ((numPairsTotal - 1) * 2);\n\n    PM4_ME_TYPE_3_HEADER header = Type3Header(IT_SET_SH_REG_PAIRS, packetSize, ResetFilterCam, ShaderType);\n\n    uint32* pPacket = static_cast<uint32*>(pBuffer);\n    pPacket[0] = header.u32All;\n\n    *ppDataStart = &pPacket[1];\n\n    return packetSize;",
  "lang": "cpp",
  "repoName": "pal",
  "url": "https://github.com/GPUOpen-Drivers/pal/blob/c5e800072a32f68b6ccc4422936d96167c6e0728/src/core/hw/gfxip/gfx12/gfx12CmdUtil.cpp#L340-L356"
 },
 "gfx9-set-sh-seq": {
  "id": "gfx9-set-sh-seq",
  "title": "SET_SH_REG: contiguous register range (GFX10/11 HWL)",
  "layer": "pal",
  "repo": "pal",
  "path": "src/core/hw/gfxip/gfx9/gfx9CmdUtil.cpp",
  "explain": "The classic register write: a header, then the offset of the first register relative to <code>PERSISTENT_SPACE_START</code> (the SH register window), then one value DWORD per register. The caller writes the values after this header. <code>SET_CONTEXT_REG</code> works the same way for context registers.",
  "symbols": [
   "IT_SET_SH_REG",
   "PERSISTENT_SPACE_START"
  ],
  "refs": [],
  "start": 4010,
  "end": 4027,
  "code": "size_t CmdUtil::BuildSetSeqShRegs(\n    uint32        startRegAddr,\n    uint32        endRegAddr,\n    Pm4ShaderType shaderType,\n    void*         pBuffer       // [out] Build the PM4 packet in this buffer.\n    ) const\n{\n#if PAL_ENABLE_PRINTS_ASSERTS\n    CheckShadowedShRegs(shaderType, startRegAddr, endRegAddr);\n#endif\n\n    auto* const  pPacket    = static_cast<PM4_ME_SET_SH_REG*>(pBuffer);\n    const uint32 packetSize = ShRegSizeDwords + endRegAddr - startRegAddr + 1;\n\n    pPacket->ordinal1.u32All = Type3Header(IT_SET_SH_REG, packetSize, false, shaderType).u32All;\n    pPacket->ordinal2.u32All = Type3Ordinal2((startRegAddr - PERSISTENT_SPACE_START), 0);\n\n    return packetSize;",
  "lang": "cpp",
  "repoName": "pal",
  "url": "https://github.com/GPUOpen-Drivers/pal/blob/c5e800072a32f68b6ccc4422936d96167c6e0728/src/core/hw/gfxip/gfx9/gfx9CmdUtil.cpp#L4010-L4027"
 },
