DRV.glossary = {
 "BO": {
  "slug": "bo",
  "long": "Buffer Object",
  "def": "A kernel-managed allocation of GPU-accessible memory (a DRM GEM object backed by TTM). Created by <code>AMDGPU_GEM_CREATE</code>; user space refers to it by a handle."
 },
 "IB": {
  "slug": "ib",
  "long": "Indirect Buffer",
  "def": "A chunk of PM4 commands in GPU memory. User space submits IBs by GPU VA and size; the kernel emits an <code>INDIRECT_BUFFER</code> packet on a ring that points at it."
 },
 "GART": {
  "slug": "gart",
  "long": "Graphics Address Remapping Table",
  "def": "System (host) memory made GPU-accessible through GPU page tables. The kernel calls this domain GTT. PAL exposes it as two heaps: <code>GpuHeapGartUswc</code> (write-combined) and <code>GpuHeapGartCacheable</code> (CPU-cached)."
 },
 "GTT": {
  "slug": "gtt",
  "long": "Graphics Translation Table",
  "def": "The amdgpu kernel's name for the system-memory domain (<code>AMDGPU_GEM_DOMAIN_GTT</code>). PAL's GART heaps map to it."
 },
 "VRAM": {
  "slug": "vram",
  "long": "Video RAM",
  "def": "Device-local memory (<code>AMDGPU_GEM_DOMAIN_VRAM</code>). PAL splits it into <code>GpuHeapLocal</code> (CPU-visible BAR window) and <code>GpuHeapInvisible</code>."
 },
 "USWC": {
  "slug": "uswc",
  "long": "Uncached Speculative Write-Combining",
  "def": "A CPU caching mode: writes are combined and streamed, and reads are uncached and slow. Good for CPU\u2192GPU upload buffers. Requested with <code>AMDGPU_GEM_CREATE_CPU_GTT_USWC</code>."
 },
 "VA": {
  "slug": "va",
  "long": "GPU Virtual Address",
  "def": "An address in the process's GPU virtual address space. Reserving a VA (libdrm <code>amdgpu_va_range_alloc</code>) is separate from backing it with a BO and mapping it (<code>AMDGPU_GEM_VA</code>)."
 },
 "PM4": {
  "slug": "pm4",
  "long": "Packet Manager 4 command format",
  "def": "The command format the GPU command processor parses. Type-3 packets have a 32-bit header (opcode, payload count, shader type, predicate) followed by payload DWORDs."
 },
 "CP": {
  "slug": "cp",
  "long": "Command Processor",
  "def": "The GPU front-end microcontrollers (PFP/ME for graphics, MEC for compute) that fetch and execute PM4."
 },
 "LLPC": {
  "slug": "llpc",
  "long": "LLVM-Based Pipeline Compiler",
  "def": "AMD's Vulkan pipeline compiler library. Its front end translates SPIR-V to LLVM IR; it also contains LGC and drives the LLVM AMDGPU backend."
 },
 "LGC": {
  "slug": "lgc",
  "long": "LLPC middle end (\"LLVM-based Graphics Compiler\")",
  "def": "LLPC's middle end (<code>llpc/lgc</code>). It lowers <code>lgc::Builder</code> operations into AMDGPU-ready IR using the pipeline state (vertex formats, color formats, descriptor layout, GFX IP) and emits the PAL pipeline ABI."
 },
 "XGL": {
  "slug": "xgl",
  "long": "Vulkan API layer",
  "def": "The repo that implements the Vulkan ICD for AMDVLK (<code>icd/api</code>). It translates Vulkan calls into PAL calls."
 },
 "PAL": {
  "slug": "pal",
  "long": "Platform Abstraction Library",
  "def": "AMD's shared GPU abstraction layer, used by several AMD drivers. It hides hardware generation (HWL) and OS (amdgpu) details."
 },
 "HWL": {
  "slug": "hwl",
  "long": "Hardware Layer",
  "def": "PAL's per-GPU-generation implementation (<code>hw/gfxip/gfx9</code>, <code>hw/gfxip/gfx12</code>) that builds PM4 and register state."
 },
 "ICD": {
  "slug": "icd",
  "long": "Installable Client Driver",
  "def": "A Vulkan driver loaded by the Khronos loader through a JSON manifest. AMDVLK's ICD is XGL."
 },
 "syncobj": {
  "slug": "syncobj",
  "long": "DRM synchronization object",
  "def": "A kernel container for a dma_fence, optionally a timeline of fences indexed by a 64-bit point. Used for Vulkan fences, binary semaphores and timeline semaphores."
 },
 "SDMA": {
  "slug": "sdma",
  "long": "System DMA engine",
  "def": "A copy engine with its own ring (<code>AMDGPU_HW_IP_DMA</code>). It runs PAL's DMA queues (Vulkan transfer queues)."
 },
 "NGG": {
  "slug": "ngg",
  "long": "Next-Generation Geometry",
  "def": "The primitive-shader geometry pipeline of GFX10+. LGC generates it and makes it mandatory on GFX11+."
 },
 "ELF": {
  "slug": "elf",
  "long": "Executable and Linkable Format",
  "def": "The container LLPC emits: ISA in .text plus a PAL metadata note (MsgPack) describing register values, user-data layout and resource usage."
 },
 "SRD": {
  "slug": "srd",
  "long": "Shader Resource Descriptor",
  "def": "A 4- or 8-DWORD hardware descriptor for a buffer, image or sampler, read by shaders from descriptor memory."
 },
 "SPIR-V": {
  "slug": "spirv",
  "long": "Standard Portable IR (Vulkan shader binary)",
  "def": "The shader IR an application passes to <code>vkCreateShaderModule</code>. LLPC parses it with its SPIRV reader."
 },
 "ISA": {
  "slug": "isa",
  "long": "Instruction Set Architecture",
  "def": "The GPU machine code (e.g. RDNA3 for gfx11) produced by the LLVM AMDGPU backend."
 },
 "GEM": {
  "slug": "gem",
  "long": "Graphics Execution Manager",
  "def": "The DRM core's buffer-object framework. amdgpu BOs are GEM objects."
 },
 "TTM": {
  "slug": "ttm",
  "long": "Translation Table Manager",
  "def": "The DRM memory manager that places and evicts BOs between VRAM and system memory. Not traced in detail on this site."
 },
 "MEC": {
  "slug": "mec",
  "long": "Micro Engine Compute",
  "def": "The CP block that runs compute queues (ACE). PAL compute queues map to <code>AMDGPU_HW_IP_COMPUTE</code>."
 },
 "residency": {
  "slug": "residency",
  "long": "memory residency",
  "def": "Guaranteeing that every BO a submission might touch is present and mapped while the GPU runs. On amdgpu this is done with the per-submit BO list, or by creating BOs <code>VM_ALWAYS_VALID</code>."
 }
};
